/**
 * Sales-document list engine. GENERATED by tools/sync-sales-doc-list.mjs from web/pages/sales_doc_type_list.xhtml + components/sales_doc_list_{mockup,legacy}.xhtml — do not edit; change the script and run `npm run sales-doc-list:sync`.
 *
 * The inline scripts of the Java list pages, same behaviour line by line: the table of the five document types (resources/support/
 * sales_doc_list_mockup.js — no API yet, so no rows: "ไม่พบข้อมูล") and, for an unknown type, the legacy list (search pill, product / status
 * menus, add button).
 *
 * WHY it is imperative DOM code and not Angular components: the Java page draws its HTML from data as strings. Porting it 1:1 is what
 * guarantees the screen, texts and states are identical to the production system.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java files (all of it lives in tools/sync-sales-doc-list.mjs):
 *   - the environment is injected (SalesDocListEnv): messages, SweetAlert, navigation, the key of the type — in Java these were EL, the URL and globals;
 *   - the five `SalesDocListMockup.init({ cols, withRef })` calls of the five pages are one call with the values of the type (QML_VARIANTS);
 *   - `list.render([])` is `list.render(env.rows)`: the host hands the rows over (the Java page has no list API yet: always none);
 *   - the strip of tabs that sales_doc_tabs.xhtml injects into the Java top bar is drawn by the Angular shell (nav.config.ts);
 *   - the links to the forms are their routes; the document listener is added through listen() and removed by destroy().
 */

export interface SalesDocListEnv {
  /** commonBean.msg['key'] in the active language */
  t: (key: string) => string;
  /** SweetAlert v2 (js/sweetalert/sweetalertv1.min.js) */
  swal: (options: Record<string, unknown>) => Promise<unknown>;
  /** window.location.href = … : the route of this app */
  navigate: (route: string) => void;
  /** the validated document type of the address: qt | bk | ob | aq | ad, or '' (unknown = the legacy list) */
  docKey: string;
  /** the rows of the table: { no, date: 'yyyy-MM-dd', customer, ref (bookings), employee, total, status, isNew } — none until the API exists */
  rows: { no: string; date: string; customer: string; ref?: string; employee: string; total: number | string; status: string; isNew?: boolean }[];
}

export function startSalesDocList(env: SalesDocListEnv): () => void {
  var destroyed = false;
  var disposers = [];
  var timers = [];
  var observers = [];
  function listen(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    disposers.push(function () { target.removeEventListener(type, fn, opts); });
  }
  function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
  function track(o) { observers.push(o); return o; }
  /* document.readyState / DOMContentLoaded / load of the page the script was written for (see the generator) */
  var readyState = 'loading';
  var readyQueue = [];
  var loadQueue = [];
  function onReady(fn) { if (readyState === 'loading') { readyQueue.push(fn); } else { tmo(fn, 0); } }
  function onLoad(fn) { if (readyState !== 'complete') { loadQueue.push(fn); } else { tmo(fn, 0); } }
  function runQueue(queue, type) {
    queue.splice(0).forEach(function (fn) {
      try { fn.call(type === 'load' ? window : document, new Event(type)); } catch (e) { console.error(e); }
    });
  }

  /* Nothing that is still in flight when the screen is left may repaint it: after destroy() a request never settles. */
  var rawFetch = env.fetch;
  var never = function () { return new Promise(function () {}); };
  var guardResponse = function (r) {
    return {
      ok: r.ok, status: r.status, statusText: r.statusText, headers: r.headers, url: r.url,
      clone: function () { return guardResponse(r.clone()); },
      json: function () { return r.json().then(function (v) { return destroyed ? never() : v; }); },
      text: function () { return r.text().then(function (v) { return destroyed ? never() : v; }); },
      blob: function () { return r.blob().then(function (v) { return destroyed ? never() : v; }); },
      arrayBuffer: function () { return r.arrayBuffer().then(function (v) { return destroyed ? never() : v; }); }
    };
  };
  env = Object.assign({}, env, {
    fetch: function (a, b) {
      if (destroyed) { return never(); }
      return rawFetch(a, b).then(
        function (r) { return destroyed ? never() : guardResponse(r); },
        function (e) { return destroyed ? never() : Promise.reject(e); });
    }
  });

  /* ---- resources/support/sales_doc_list_mockup.js ---- */
  (function () {
      var CENT = 100;
      var PRINT_ICON = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9V2h12v7"></path><rect x="6" y="14" width="12" height="8"></rect><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path></svg>';
  
      function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
      /* yyyy-MM-dd → dd/MM/yyyy (ค่าอื่นแสดงตามที่ได้) */
      function viewDate(s) { var p = String(s == null ? '' : s).split('-'); return p.length === 3 ? p[2] + '/' + p[1] + '/' + p[0] : String(s || ''); }
      function money(v) {
          var n = typeof v === 'number' ? v : parseFloat(String(v == null ? '' : v).replace(/,/g, ''));
          if (!isFinite(n)) { return esc(v); }
          return (Math.round((n + Number.EPSILON) * CENT) / CENT).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      }
  
      function init(o) {
          var body = document.getElementById(o.bodyId);
          var msg = o.msg || {};
          if (!body) { return { render: function () {} }; }
          var current = [], handler = null;
  
          function rowHtml(r, i) {
              return '<tr' + (r.isNew ? ' class="qml-new"' : '') + '>'
                  + '<td class="qml-no">' + esc(r.no) + '</td>'
                  + '<td class="qml-nowrap">' + esc(viewDate(r.date)) + '</td>'
                  + '<td>' + esc(r.customer) + '</td>'
                  + (o.withRef ? '<td class="qml-nowrap">' + esc(r.ref || '-') + '</td>' : '')
                  + '<td>' + esc(r.employee) + '</td>'
                  + '<td class="r">' + money(r.total) + '</td>'
                  + '<td class="qml-nowrap">' + esc(r.status) + '</td>'
                  + '<td class="c"><button type="button" class="qml-pbtn" data-print="' + i + '"' + (handler ? '' : ' disabled="disabled"')
                  + ' aria-label="' + esc((msg.print || '') + ' ' + (r.no || '')) + '">' + PRINT_ICON + '</button></td></tr>';
          }
  
          body.addEventListener('click', function (e) {
              var b = e.target.closest && e.target.closest('[data-print]');
              if (!b || !handler) { return; }
              var row = current[+b.getAttribute('data-print')];
              if (row) { handler(row); }
          });
  
          return {
              render: function (rows, opt) {
                  current = rows || [];
                  handler = opt && typeof opt.onPrint === 'function' ? opt.onPrint : null;
                  body.innerHTML = current.length
                      ? current.map(rowHtml).join('')
                      : '<tr class="qml-empty"><td colspan="' + (o.cols || 7) + '">' + esc(msg.empty) + '</td></tr>';
              }
          };
      }
  
      window.SalesDocListMockup = { init: init };
  })();  var QML_VARIANTS = {"qt":{"cols":7,"withRef":false},"bk":{"cols":8,"withRef":true},"ob":{"cols":7,"withRef":false},"aq":{"cols":7,"withRef":false},"ad":{"cols":7,"withRef":false}};

  if (env.docKey) {
    /* ---- components/sales_doc_list_mockup.xhtml (one of the five types) ---- */
              var list = SalesDocListMockup.init({
                  bodyId: 'qmlBody',
                  cols: QML_VARIANTS[env.docKey].cols,
                  withRef: QML_VARIANTS[env.docKey].withRef,
                  msg: { empty: env.t("label.dashboard.no_data"), print: env.t("label.qtl.col_print") }
              });
              /* ยังไม่มี API รายการเอกสาร → ไม่มีแถว ; มี API แล้ว: list.render([{ no, date: 'yyyy-MM-dd', customer, ref (เฉพาะใบจอง), employee, total, status, isNew }], { onPrint: function (row) { ... } }) */
              list.render(env.rows);
  } else {
    /* ---- components/sales_doc_list_legacy.xhtml (no / unknown type) ---- */
                  var NO_DATA_ROW = ('<tr class="sdt-empty"><td colspan="10" style="text-align:center; color:#9AA0AE; padding:28px;">' + env.t("label.dashboard.no_data") + '</td></tr>');
                  var body = document.getElementById('sd2Body');
                  var productMenu = document.getElementById('sd2ProductMenu');
                  var filterMenu = document.getElementById('sd2FilterMenu');
                  var searchWrap = document.getElementById('sd2Search');
                  var searchInput = document.getElementById('sd2SearchInput');
  
                  function closeAll() {
                      [productMenu, filterMenu].forEach(function (el) { if (el) { el.classList.remove('show'); } });
                  }
                  function toggleMenu(menu) {
                      var willOpen = !menu.classList.contains('show');
                      closeAll();
                      if (willOpen) { menu.classList.add('show'); }
                  }
  
                  /* กรองแถวตามช่องค้นหา + นับจำนวนที่ footer (ยังไม่มีข้อมูลจริง = แสดง 0 จาก 0) */
                  function sdtApplyFilters() {
                      var q = ((searchInput && searchInput.value) || '').trim().toLowerCase();
                      var rows = body.querySelectorAll('tr:not(.sdt-empty)');
                      var shown = 0;
                      rows.forEach(function (tr) {
                          var vis = !q || (tr.getAttribute('data-s') || '').indexOf(q) !== -1;
                          tr.style.display = vis ? '' : 'none';
                          if (vis) { shown++; }
                      });
                      if (!rows.length) { body.innerHTML = NO_DATA_ROW; }
                      var foot = document.querySelector('.sd2-foot span');
                      if (foot) { foot.textContent = env.t("label.rv.showing").replace('{0}', shown).replace('{1}', rows.length); }
                  }
                  window.sdtApplyFilters = sdtApplyFilters;
  
                  // ---------- ช่องค้นหา (pill ขยาย แบบเดียวกับหน้าใบรับเงิน) ----------
                  function openSearch() { searchWrap.classList.add('open'); searchInput.focus(); }
                  function closeSearch() { searchWrap.classList.remove('open'); searchInput.value = ''; sdtApplyFilters(); }
                  document.getElementById('sd2SearchBtn').addEventListener('click', function (e) {
                      e.stopPropagation();
                      if (searchWrap.classList.contains('open')) { searchInput.focus(); } else { openSearch(); }
                  });
                  document.getElementById('sd2SearchGo').addEventListener('click', function (e) { e.stopPropagation(); sdtApplyFilters(); });
                  document.getElementById('sd2SearchClear').addEventListener('click', function (e) { e.stopPropagation(); closeSearch(); });
                  searchInput.addEventListener('input', sdtApplyFilters);
                  searchInput.addEventListener('keydown', function (e) {
                      if (e.key === 'Enter') { e.preventDefault(); sdtApplyFilters(); }
                      else if (e.key === 'Escape') { closeSearch(); }
                  });
  
                  // ---------- ดรอปดาวน์ผลิตภัณฑ์ / ตัวกรอง ----------
                  document.getElementById('sd2ProductBtn').addEventListener('click', function (e) { e.stopPropagation(); toggleMenu(productMenu); });
                  document.getElementById('sd2FilterBtn').addEventListener('click', function (e) { e.stopPropagation(); toggleMenu(filterMenu); });
                  [productMenu, filterMenu].forEach(function (menu) {
                      menu.addEventListener('click', function (e) { e.stopPropagation(); menu.classList.remove('show'); });
                  });
                  listen(document, 'click', closeAll);
  
                  // ---------- ปุ่มเพิ่มใหม่ ----------
                  //   ใบเสนอราคา (qt) → ฟอร์มสร้างเอกสาร sales_doc_qt_form.xhtml (★ 28/09)
                  //   เอกสารอื่นยังไม่มีฟอร์ม → แจ้งว่าอยู่ระหว่างพัฒนา
                  //   ★ 15/10/2026: ใบเสนอราคารถยนต์ (aq) / ใบจองรถยนต์ (ad) → sales_doc_aq_form / sales_doc_ad_form.xhtml (Mockup v23 Auto Dealer)
                  var ADD_FORM_BY_DOC = {
                      qt: '/sales/docs/qt/new', bk: '/sales/docs/bk/new', ob: '/sales/docs/ob/new',
                      aq: '/sales/docs/aq/new', ad: '/sales/docs/ad/new'
                  };
                  var DOC_KEY = '';
                  var addBtn = document.getElementById('sd2AddBtn');
                  if (addBtn) {
                      addBtn.addEventListener('click', function () {
                          if (ADD_FORM_BY_DOC[DOC_KEY]) { env.navigate(ADD_FORM_BY_DOC[DOC_KEY]); return; }
                          env.swal({ title: env.t("label.ld2.sale_docs"), text: env.t("label.sales_doc_tab.not_ready"), icon: 'info', timer: 3000, buttons: false });
                      });
                  }
  
                  sdtApplyFilters();
  }

  /* the entry points of the inline handlers and of the window.* functions */
  
  var EXPORTED = ["SalesDocListMockup","sdtApplyFilters"];

  /* "the document has been parsed": DOMContentLoaded handlers in the order they were registered, then "load" */
  readyState = 'interactive';
  runQueue(readyQueue, 'DOMContentLoaded');
  readyState = 'complete';
  tmo(function () { runQueue(loadQueue, 'load'); }, 0);

  return function destroy() {
    destroyed = true;
    disposers.splice(0).forEach(function (d) { d(); });
    timers.splice(0).forEach(function (h) { clearTimeout(h); });
    observers.splice(0).forEach(function (o) { o.disconnect(); });
    EXPORTED.forEach(function (n) { try { delete window[n]; } catch (e) { window[n] = undefined; } });
  };
}
